/**
 * jQuery 3.7.0 - Essential Functions for Teddy Bear Shop
 * Simplified version with core functionality needed for the project
 */

(function(global) {
    'use strict';

    function jQuery(selector) {
        return new jQuery.fn.init(selector);
    }

    jQuery.fn = jQuery.prototype = {
        constructor: jQuery,
        length: 0,

        init: function(selector) {
            if (!selector) return this;

            if (typeof selector === 'string') {
                if (selector === 'document') {
                    this[0] = document;
                    this.length = 1;
                } else if (selector === 'window') {
                    this[0] = window;
                    this.length = 1;
                } else {
                    const elements = document.querySelectorAll(selector);
                    this.length = elements.length;
                    for (let i = 0; i < elements.length; i++) {
                        this[i] = elements[i];
                    }
                }
            } else if (selector.nodeType) {
                this[0] = selector;
                this.length = 1;
            } else if (typeof selector === 'function') {
                if (document.readyState === 'loading') {
                    document.addEventListener('DOMContentLoaded', selector);
                } else {
                    selector();
                }
            }

            return this;
        },

        each: function(callback) {
            for (let i = 0; i < this.length; i++) {
                callback.call(this[i], i, this[i]);
            }
            return this;
        },

        addClass: function(className) {
            return this.each(function() {
                if (this.classList) {
                    this.classList.add(className);
                }
            });
        },

        removeClass: function(className) {
            return this.each(function() {
                if (this.classList) {
                    this.classList.remove(className);
                }
            });
        },

        toggleClass: function(className) {
            return this.each(function() {
                if (this.classList) {
                    this.classList.toggle(className);
                }
            });
        },

        hasClass: function(className) {
            return this[0] && this[0].classList && this[0].classList.contains(className);
        },

        css: function(property, value) {
            if (typeof property === 'object') {
                return this.each(function() {
                    for (let prop in property) {
                        this.style[prop] = property[prop];
                    }
                });
            } else if (value !== undefined) {
                return this.each(function() {
                    this.style[property] = value;
                });
            } else {
                return this[0] ? getComputedStyle(this[0])[property] : null;
            }
        },

        attr: function(name, value) {
            if (value !== undefined) {
                return this.each(function() {
                    this.setAttribute(name, value);
                });
            }
            return this[0] ? this[0].getAttribute(name) : null;
        },

        prop: function(name, value) {
            if (value !== undefined) {
                return this.each(function() {
                    this[name] = value;
                });
            }
            return this[0] ? this[0][name] : null;
        },

        val: function(value) {
            if (value !== undefined) {
                return this.each(function() {
                    this.value = value;
                });
            }
            return this[0] ? this[0].value : null;
        },

        text: function(text) {
            if (text !== undefined) {
                return this.each(function() {
                    this.textContent = text;
                });
            }
            return this[0] ? this[0].textContent : null;
        },

        html: function(html) {
            if (html !== undefined) {
                return this.each(function() {
                    this.innerHTML = html;
                });
            }
            return this[0] ? this[0].innerHTML : null;
        },

        append: function(content) {
            return this.each(function() {
                if (typeof content === 'string') {
                    this.insertAdjacentHTML('beforeend', content);
                } else {
                    this.appendChild(content);
                }
            });
        },

        prepend: function(content) {
            return this.each(function() {
                if (typeof content === 'string') {
                    this.insertAdjacentHTML('afterbegin', content);
                } else {
                    this.insertBefore(content, this.firstChild);
                }
            });
        },

        after: function(content) {
            return this.each(function() {
                if (typeof content === 'string') {
                    this.insertAdjacentHTML('afterend', content);
                } else {
                    this.parentNode.insertBefore(content, this.nextSibling);
                }
            });
        },

        remove: function() {
            return this.each(function() {
                if (this.parentNode) {
                    this.parentNode.removeChild(this);
                }
            });
        },

        hide: function() {
            return this.css('display', 'none');
        },

        show: function() {
            return this.css('display', '');
        },

        fadeIn: function(duration = 300) {
            return this.each(function() {
                this.style.opacity = '0';
                this.style.display = '';
                
                const start = performance.now();
                const animate = (time) => {
                    const elapsed = time - start;
                    const progress = Math.min(elapsed / duration, 1);
                    this.style.opacity = progress;
                    
                    if (progress < 1) {
                        requestAnimationFrame(animate);
                    }
                };
                requestAnimationFrame(animate);
            });
        },

        fadeOut: function(duration = 300, callback) {
            return this.each(function() {
                const start = performance.now();
                const initialOpacity = parseFloat(getComputedStyle(this).opacity) || 1;
                
                const animate = (time) => {
                    const elapsed = time - start;
                    const progress = Math.min(elapsed / duration, 1);
                    this.style.opacity = initialOpacity * (1 - progress);
                    
                    if (progress < 1) {
                        requestAnimationFrame(animate);
                    } else {
                        this.style.display = 'none';
                        if (callback) callback.call(this);
                    }
                };
                requestAnimationFrame(animate);
            });
        },

        slideUp: function(duration = 300, callback) {
            return this.each(function() {
                const height = this.offsetHeight;
                this.style.overflow = 'hidden';
                this.style.transition = `height ${duration}ms ease`;
                this.style.height = height + 'px';
                
                setTimeout(() => {
                    this.style.height = '0px';
                }, 10);
                
                setTimeout(() => {
                    this.style.display = 'none';
                    this.style.transition = '';
                    this.style.height = '';
                    this.style.overflow = '';
                    if (callback) callback.call(this);
                }, duration);
            });
        },

        slideDown: function(duration = 300, callback) {
            return this.each(function() {
                this.style.display = '';
                const height = this.offsetHeight;
                this.style.height = '0px';
                this.style.overflow = 'hidden';
                this.style.transition = `height ${duration}ms ease`;
                
                setTimeout(() => {
                    this.style.height = height + 'px';
                }, 10);
                
                setTimeout(() => {
                    this.style.transition = '';
                    this.style.height = '';
                    this.style.overflow = '';
                    if (callback) callback.call(this);
                }, duration);
            });
        },

        animate: function(properties, duration = 400, callback) {
            return this.each(function() {
                const element = this;
                const start = performance.now();
                const startValues = {};
                
                for (let prop in properties) {
                    startValues[prop] = parseFloat(getComputedStyle(element)[prop]) || 0;
                }
                
                const animate = (time) => {
                    const elapsed = time - start;
                    const progress = Math.min(elapsed / duration, 1);
                    
                    for (let prop in properties) {
                        const startValue = startValues[prop];
                        const endValue = parseFloat(properties[prop]);
                        const currentValue = startValue + (endValue - startValue) * progress;
                        element.style[prop] = currentValue + (prop.includes('opacity') ? '' : 'px');
                    }
                    
                    if (progress < 1) {
                        requestAnimationFrame(animate);
                    } else if (callback) {
                        callback.call(element);
                    }
                };
                requestAnimationFrame(animate);
            });
        },

        on: function(event, selector, handler) {
            if (typeof selector === 'function') {
                handler = selector;
                selector = null;
            }

            return this.each(function() {
                if (selector) {
                    // Event delegation
                    this.addEventListener(event, function(e) {
                        if (e.target.matches(selector)) {
                            handler.call(e.target, e);
                        }
                    });
                } else {
                    this.addEventListener(event, handler);
                }
            });
        },

        off: function(event, handler) {
            return this.each(function() {
                this.removeEventListener(event, handler);
            });
        },

        click: function(handler) {
            if (handler) {
                return this.on('click', handler);
            } else {
                return this.each(function() {
                    this.click();
                });
            }
        },

        submit: function(handler) {
            if (handler) {
                return this.on('submit', handler);
            } else {
                return this.each(function() {
                    if (this.submit) this.submit();
                });
            }
        },

        change: function(handler) {
            return this.on('change', handler);
        },

        input: function(handler) {
            return this.on('input', handler);
        },

        keypress: function(handler) {
            return this.on('keypress', handler);
        },

        keydown: function(handler) {
            return this.on('keydown', handler);
        },

        scroll: function(handler) {
            return this.on('scroll', handler);
        },

        resize: function(handler) {
            return this.on('resize', handler);
        },

        hover: function(enterHandler, leaveHandler) {
            return this.on('mouseenter', enterHandler).on('mouseleave', leaveHandler || enterHandler);
        },

        focus: function(handler) {
            if (handler) {
                return this.on('focus', handler);
            } else {
                return this.each(function() {
                    this.focus();
                });
            }
        },

        blur: function(handler) {
            if (handler) {
                return this.on('blur', handler);
            } else {
                return this.each(function() {
                    this.blur();
                });
            }
        },

        find: function(selector) {
            const result = jQuery();
            this.each(function() {
                const found = this.querySelectorAll(selector);
                for (let i = 0; i < found.length; i++) {
                    result[result.length++] = found[i];
                }
            });
            return result;
        },

        parent: function() {
            const result = jQuery();
            this.each(function() {
                if (this.parentNode && this.parentNode.nodeType === 1) {
                    result[result.length++] = this.parentNode;
                }
            });
            return result;
        },

        children: function() {
            const result = jQuery();
            this.each(function() {
                for (let child of this.children) {
                    result[result.length++] = child;
                }
            });
            return result;
        },

        siblings: function() {
            const result = jQuery();
            this.each(function() {
                const siblings = Array.from(this.parentNode.children).filter(child => child !== this);
                for (let sibling of siblings) {
                    result[result.length++] = sibling;
                }
            });
            return result;
        },

        closest: function(selector) {
            const result = jQuery();
            this.each(function() {
                const closest = this.closest(selector);
                if (closest) {
                    result[result.length++] = closest;
                }
            });
            return result;
        },

        is: function(selector) {
            return this[0] && this[0].matches(selector);
        },

        offset: function() {
            if (!this[0]) return null;
            const rect = this[0].getBoundingClientRect();
            return {
                top: rect.top + window.scrollY,
                left: rect.left + window.scrollX
            };
        },

        position: function() {
            if (!this[0]) return null;
            return {
                top: this[0].offsetTop,
                left: this[0].offsetLeft
            };
        },

        width: function() {
            return this[0] ? this[0].offsetWidth : null;
        },

        height: function() {
            return this[0] ? this[0].offsetHeight : null;
        },

        outerWidth: function() {
            if (!this[0]) return null;
            const style = getComputedStyle(this[0]);
            return this[0].offsetWidth + parseFloat(style.marginLeft) + parseFloat(style.marginRight);
        },

        outerHeight: function() {
            if (!this[0]) return null;
            const style = getComputedStyle(this[0]);
            return this[0].offsetHeight + parseFloat(style.marginTop) + parseFloat(style.marginBottom);
        },

        scrollTop: function(value) {
            if (value !== undefined) {
                return this.each(function() {
                    this.scrollTop = value;
                });
            }
            return this[0] ? this[0].scrollTop : null;
        },

        scrollLeft: function(value) {
            if (value !== undefined) {
                return this.each(function() {
                    this.scrollLeft = value;
                });
            }
            return this[0] ? this[0].scrollLeft : null;
        }
    };

    jQuery.fn.init.prototype = jQuery.fn;

    // Static methods
    jQuery.ajax = function(options) {
        const defaults = {
            method: 'GET',
            url: '',
            data: null,
            dataType: 'json',
            contentType: 'application/x-www-form-urlencoded',
            headers: {},
            beforeSend: function() {},
            success: function() {},
            error: function() {},
            complete: function() {}
        };

        const settings = Object.assign({}, defaults, options);
        
        settings.beforeSend();

        const xhr = new XMLHttpRequest();
        xhr.open(settings.method, settings.url, true);

        // Set headers
        for (let header in settings.headers) {
            xhr.setRequestHeader(header, settings.headers[header]);
        }

        if (settings.method === 'POST' && settings.contentType) {
            xhr.setRequestHeader('Content-Type', settings.contentType);
        }

        xhr.onreadystatechange = function() {
            if (xhr.readyState === 4) {
                if (xhr.status >= 200 && xhr.status < 300) {
                    let response = xhr.responseText;
                    if (settings.dataType === 'json') {
                        try {
                            response = JSON.parse(response);
                        } catch (e) {
                            settings.error(xhr, 'parsererror', e);
                            settings.complete(xhr, 'parsererror');
                            return;
                        }
                    }
                    settings.success(response, 'success', xhr);
                } else {
                    settings.error(xhr, 'error', xhr.statusText);
                }
                settings.complete(xhr, xhr.status >= 200 && xhr.status < 300 ? 'success' : 'error');
            }
        };

        // Prepare data
        let data = settings.data;
        if (data && typeof data === 'object' && !(data instanceof FormData)) {
            if (settings.contentType.includes('application/json')) {
                data = JSON.stringify(data);
            } else {
                const params = new URLSearchParams();
                for (let key in data) {
                    params.append(key, data[key]);
                }
                data = params.toString();
            }
        }

        xhr.send(data);
    };

    jQuery.ajaxSetup = function(options) {
        jQuery.ajaxDefaults = Object.assign(jQuery.ajaxDefaults || {}, options);
    };

    // Global $ and jQuery
    global.$ = global.jQuery = jQuery;

})(window);